import{_ as r}from"./chunks/PM_work.B_kLj-6q.js";import{_ as t,o as a,c as p,a2 as l}from"./chunks/framework.CHeM0PsO.js";const o="/img/whole_process.png",i="/img/whole_project.png",g=JSON.parse('{"title":"全流程知识","description":"","frontmatter":{},"headers":[],"relativePath":"knowledge/index.md","filePath":"knowledge/index.md","lastUpdated":null}'),n={name:"knowledge/index.md"};function s(_,e,m,c,h,d){return a(),p("div",null,[...e[0]||(e[0]=[l('<h1 id="全流程知识" tabindex="-1">全流程知识 <a class="header-anchor" href="#全流程知识" aria-label="Permalink to &quot;全流程知识&quot;">​</a></h1><p><img src="'+o+'" alt="整个产品实现的流程和生命周期1"></p><p><img src="'+i+'" alt="完整项目的角色"></p><p><img src="'+r+'" alt="产品经理的工作职能6"></p><ul><li>领域专家：用无人机看书，农业专家对二月份的树该有大致的样子是清楚的。甲方翻译成任务交给数据科学家（乙方）去提高。</li><li>数据科学家：关心实际业务问题。不断开发新领域。</li><li>AI专家：不仅能用，精度性能。领域做深。<a href="https://www.bilibili.com/video/BV1J54y187f9/?p=2&amp;spm_id_from=pageDriver" target="_blank" rel="noreferrer">4</a></li></ul><p>自然语言处理不如图片应用做的好。</p><p><a href="https://i.am.ai/roadmap" target="_blank" rel="noreferrer">https://i.am.ai/roadmap</a></p><p>AI产品经理的进阶地图 - 知乎 <a href="https://www.zhihu.com/club/1266018382773624832/post/1266047295663403008" target="_blank" rel="noreferrer">https://www.zhihu.com/club/1266018382773624832/post/1266047295663403008</a></p><p>AI产品经理是“产品经理”这个职业的一个分支，在成为AI产品经理之前，你需要先成为一名合格的产品经理（拥有产品思维、产品经理相关的知识体系）</p><p>第0阶段：产品经理基础知识 ———————————————— 产品经理知识架构（C端产品经理、B端产品经理、策略产品经理、数据产品经理）</p><ol><li>商业分析、市场分析、需求分析；</li><li>产品设计：整体设计、详细设计；</li><li>项目管理：需求池管理、版本迭代管理；</li><li>产品运营：市场运营、用户运营、内容运营；</li></ol><p>第1阶段：AI产品经理的基础知识</p><p>———————————————— 1.AI产品经理基础：人工智能概论、AI产品经理职责、资源管理（数据集、算法模型、策略、软硬件资源、需求管理）、工作流程、核心技术、行业应用 2.机器学习：数据采集、数据探索、数据预处理、ML模型、模型训练、场景应用 3.深度学习：基于深度神经网络的模型应用（CNN、RNN、GAN） 4.强化学习：基于智能体/环境接口的马尔科夫过程模型；</p><p>第2阶段：AI领域的纵向深度挖掘</p><p>———————————————— 1.模式识别：图像识别、人脸识别、语音识别、视频识别等； 2.自然语言处理（NLP）：自然语言理解（NLU）、自然语言生成（NLG）、知识图谱<a href="http://www.mysecretrainbow.com/ai/18035.html" target="_blank" rel="noreferrer">2</a>等 3.智能语音：语音识别、语音合成、声纹识别 4.智能软硬件：芯片<a href="https://mbb.eet-china.com/tech" target="_blank" rel="noreferrer">5</a>、智能软硬件项目流程； 5.专家系统：基于专家知识架构的AI综合应用 6.机器人：基于生物智能的AI应用 7.其他领域的纵向深度挖掘</p><blockquote><p>（本节目录见左侧导航）</p></blockquote>',16)])])}const b=t(n,[["render",s]]);export{g as __pageData,b as default};
